void InsertAtBeginning(int[] values, int count, int newValue)
{
    for (var i = count; i > 0; i--)
        values[i] = values[i - 1];
    values[0] = newValue;
}

int[] BuildPrefix(int[] values)
{
    var prefix = new int[values.Length + 1];
    for (var i = 0; i < values.Length; i++)
        prefix[i + 1] = prefix[i] + values[i];
    return prefix;
}

